const ST=[["Quick Setup","ক্যামেরা, মাইক ও আইডি যাচাই; ছোট ওয়ার্ম-আপ (স্কোরে ধরা হয় না)","—","ছোট"],["Read and Select","একটি একটি শব্দ দেখে Yes (আসল ইংরেজি) বা No (নকল) বাছুন","১৫–১৮","৫ সেকেন্ড/শব্দ"],["Fill in the Blanks","বাক্যে একটি অসম্পূর্ণ শব্দের বাকি অক্ষর টাইপ করুন","৬–৯","২০ সেকেন্ড"],["Read and Complete","অনুচ্ছেদের অসম্পূর্ণ শব্দগুলো সম্পূর্ণ করুন","৩–৬","৩ মিনিট"],["Listen and Type","শুনে বাক্য (২০ শব্দ পর্যন্ত) হুবহু টাইপ করুন; ৩ বার শোনা যায়","৬–৯","১ মিনিট"],["Interactive Reading","এক অনুচ্ছেদে ৬ ধরনের প্রশ্ন: Complete the Sentences, Complete the Passage, Highlight the Answer (×২), Identify the Idea, Title the Passage","২–৩ অনুচ্ছেদ","৭–৮ মিনিট/অনুচ্ছেদ"],["Interactive Listening","Listen and Complete → Listen and Respond (৫–৬টি) → Summarize the Conversation","২–৩ দৃশ্য","৬:৩০ + ১:১৫"],["Write About the Photo","ছবি দেখে বর্ণনা লিখুন","৩","১ মিনিট"],["Interactive Writing","প্রশ্ন ১-এর উত্তর (৫ মিনিট), তারপর একই বিষয়ে প্রশ্ন ২ (৩ মিনিট)","১ সেট","৮ মিনিট"],["Speak About the Photo","২০ সেকেন্ড দেখুন, তারপর ৯০ সেকেন্ড পর্যন্ত বলুন; একবারই রেকর্ড","১","১:৩০"],["Read Then Speak","প্রশ্ন পড়ে ২০ সেকেন্ড প্রস্তুতি, তারপর ৯০ সেকেন্ড পর্যন্ত বলুন","১","১:৩০"],["Interactive Speaking","চরিত্র প্রশ্ন করে; প্রতিটির উত্তর ৩৫ সেকেন্ড পর্যন্ত; পরের প্রশ্ন আপনার উত্তরের ওপর নির্ভর করে","৬–৮","০:৩৫"],["Writing Sample","৩০ সেকেন্ড ভেবে ৫ মিনিট লিখুন; প্রতিষ্ঠানের কাছে পাঠানো হয়","১","৫:০০"],["Speaking Sample","৩০ সেকেন্ড ভেবে ৩ মিনিট পর্যন্ত বলুন; ভিডিও প্রতিষ্ঠানের কাছে পাঠানো হয়","১","৩:০০"]];
const TIPS=[["১. পরীক্ষার কাঠামো","DET সম্পূর্ণ অনলাইন ও AI-স্কোরড; সময় প্রায় ১ ঘণ্টা, ফলাফল সাধারণত ২ দিনের মধ্যে। Reading ও Listening-এর বেশিরভাগ অংশ adaptive (সঠিক হলে পরের প্রশ্ন কঠিন)। Writing/Speaking প্রশ্ন সাধারণত non-adaptive; একমাত্র adaptive speaking হলো Interactive Speaking। প্রশ্ন কঠিন লাগলে ঘাবড়াবেন না। সংখ্যা ও ক্রম বদলাতে পারে — অফিসিয়াল সাইট দেখে নিন।"],["২. স্কোর","মোট স্কোর ১০–১৬০ (৫ পয়েন্টের ধাপে)। এটি চারটি সাবস্কোরের গড়: Listening, Speaking, Reading, Writing। সাথে চারটি combined সাবস্কোর: Literacy, Comprehension, Conversation, Production। অনেক প্রতিষ্ঠান ন্যূনতম স্কোর চায় — আপনার টার্গেট প্রতিষ্ঠানের ওয়েবসাইটে দেখুন। ফি ও বৈধতা অফিসিয়াল সাইটে যাচাই করুন।"],["৩. পরিবেশ ও প্রযুক্তি","শান্ত, উজ্জ্বল ঘর; একা থাকুন; আপডেটেড Chrome; স্থির ইন্টারনেট; চার্জারসহ ল্যাপটপ; সরকারি আইডি হাতে। অতিরিক্ত মনিটর, হেডফোন, ফোন, নোট ও অন্য ট্যাব ব্যবহার করবেন না — টেস্ট বাতিল হতে পারে।"],["৪. Read and Select","প্রতিটি শব্দে ৫ সেকেন্ড; সময় শেষ হলে ভুল। দ্রুত সিদ্ধান্ত নিন: পরিচিত শব্দ/prefix/suffix (un-, -tion, -ment) দেখে Yes; ইংরেজির মতো শোনায় কিন্তু কোথাও দেখেননি এমন অদ্ভুত বানান হলে No। ভুল উত্তর = সঠিক/ভুল স্কোর, তাই আটকে থাকবেন না।"],["৫. Fill in the Blanks ও Read and Complete","বানান নির্ভুল না হলে নম্বর নেই। Fill in the Blanks: বাক্যের প্রসঙ্গ থেকে শব্দ অনুমান করুন। Read and Complete: আগে পুরো অনুচ্ছেদ পড়ুন; শিরোনাম, প্রথম ও শেষ বাক্যে blank থাকে না; অসম্পূর্ণ শব্দ কখনো পাশাপাশি আসে না; প্রতিটি শব্দ আলাদা স্কোর পায়। plural -s, -ed, -ing, -ly খেয়াল করুন।"],["৬. Listen and Type","২০ শব্দ পর্যন্ত বাক্য, ৩ বার শোনা যায়, ১ মিনিট সময়। আংশিক নম্বর আছে — তাই যা শুনেছেন সব লিখুন। বানান ও punctuation গুরুত্বপূর্ণ; a/an/the, -s, -ed ছেড়ে দেবেন না।"],["৭. Interactive Reading","একটি অনুচ্ছেদ ঘিরে ছয়টি কাজ। Complete the Sentences ও Complete the Passage-এ আগে-পরের বাক্যের যুক্তি দেখুন। Highlight the Answer-এ প্রশ্নের উত্তর যে বাক্যে আছে সেটি ঠিকভাবে নির্বাচন করুন (কাছাকাছি হলেও আংশিক নম্বর)। Identify the Idea ও Title the Passage-এ ছোট তথ্য নয়, পুরো অনুচ্ছেদের মূল ভাব দেখুন।"],["৮. Interactive Listening","প্রথমে Listen and Complete (যতবার খুশি শোনা যায়): ফাঁকা অংশে সঠিক ভাব লিখুন — বানান স্কোরে প্রভাব ফেলে না, তবে বেশি বা কম লিখলে নম্বর কমে। তারপর Listen and Respond: সেরা উত্তর বাছুন। শেষে Summarize the Conversation (৭৫ সেকেন্ড): কে কথা বলছে, বিষয়, মূল পয়েন্ট ও শেষ ফলাফল লিখুন।"],["৯. Write About the Photo","১ মিনিট, ৩টি ছবি। কাঠামো: ছবিতে কী আছে → কে কী করছে → পেছনের দৃশ্য → অনুমান (probably, seems)। ২–৪ বাক্য লিখুন; ছবিতে নেই এমন নাম/সংখ্যা বানাবেন না। শেষ ১০ সেকেন্ডে বানান দেখুন।"],["১০. Interactive Writing","অংশ ১: ৫ মিনিট (ভাবার জন্য ৩০ সেকেন্ড)। অংশ ২: ৩ মিনিট — একই বিষয়ে, কিন্তু নতুন একটি দিক নিয়ে লিখুন। বিষয় বদলে ফেললে নম্বর কমতে পারে। ভূমিকা → কারণ → উদাহরণ; linking words ব্যবহার করুন।"],["১১. Speak About the Photo ও Read Then Speak","২০ সেকেন্ড দেখা/প্রস্তুতি, তারপর ৯০ সেকেন্ড পর্যন্ত বলুন; পুনরায় রেকর্ড করা যায় না। পুরো সময় বলুন, থামলে ‘Let me think…’ বা প্রসঙ্গ জুড়ে এগিয়ে যান। Read Then Speak-এ প্রশ্নের সব অংশের (bullet) উত্তর দিন।"],["১২. Interactive Speaking","দুটি বিষয়ে মোট ৬–৮টি প্রশ্ন; প্রতিটির উত্তর ৩৫ সেকেন্ড পর্যন্ত; প্রশ্ন শুধু একবার শোনা যায়। প্রতিটি উত্তরে মত + কারণ + ছোট উদাহরণ দিন। পরের প্রশ্ন আপনার উত্তরের মান ও বিষয়বস্তুর ওপর নির্ভর করে।"],["১৩. Writing Sample ও Speaking Sample","এ দুটি স্কোরেও যোগ হয়, আবার প্রতিষ্ঠানকে পাঠানো হয় (Speaking Sample ভিডিওসহ)। সৎ, ব্যক্তিগত ও গোছানো উত্তর দিন: introduction → ২টি পয়েন্ট (উদাহরণসহ) → conclusion। লেখায় ৫ মিনিট, বলায় ৩ মিনিট পর্যন্ত পুরো সময় কাজে লাগান।"],["১৪. Production-এর স্কোরিং মানদণ্ড","Writing ৪টি মানদণ্ডে: content, discourse coherence, grammar, lexis। Speaking ৬টি: এগুলোর সাথে fluency ও pronunciation। অফ-টপিক, খুব ছোট বা পুনরাবৃত্তিমূলক উত্তরে খুব কম স্কোর। লেখায় UK/US দুই বানানই চলে; বলায় সহজবোধ্য যেকোনো স্ট্যান্ডার্ড উচ্চারণ গ্রহণযোগ্য।"],["১৫. সময় ব্যবস্থাপনা","সময় শেষ হলে স্বয়ংক্রিয়ভাবে পরের প্রশ্নে যায়। যা জানেন আগে লিখুন, পরে সাজান। কোনো উত্তর ফাঁকা রাখবেন না — আংশিক উত্তরেও নম্বর আছে।"],["১৬. দৈনিক রুটিন ও আগের দিন","দৈনিক: ২০ মিনিট পড়া, ২০ মিনিট শোনা (podcast/news), ১০ মিনিট লেখা, ১০ মিনিট জোরে বলা। সপ্তাহে ২টি টাইমড সেট এখানে দিন। ভুলের খাতা রাখুন। পরীক্ষার আগের দিন: ভালো ঘুম, সিস্টেম চেক, আইডি ও মাইক-ক্যামেরা প্রস্তুত।"]];
const SC=[["160","C2","8.5–9","120"],["150","C1","8","117–118"],["140","C1","7.5","109–112"],["130","C1","7","98–103"],["120","B2","6.5","87–92"],["110","B2","6","76–81"],["100","B2","5.5","65–69"],["90","B1","5","53–58"],["80","B1","5","41–46"],["70","B1","4.5","30–34"],["60","B1","4","18–23"]];
const PLAN=[["Week 1: Reading ও Listening-এর ভিত্তি",["Tips ও Scoring পৃষ্ঠা পড়ুন","Read and Select: lesson + exam","Fill in the Blanks: lesson + exam","Read and Complete: lesson + exam","Listen and Type: lesson + exam","Grammar guide (নিয়ম ১–৫) + Grammar Practice","Review: ভুলের খাতা দেখুন"]],["Week 2: Interactive tasks",["Interactive Reading: lesson + exam","Interactive Reading: আবার (নতুন সেট)","Interactive Listening: lesson + exam","Vocabulary Practice + ২০টি নতুন শব্দ","Grammar guide (নিয়ম ৬–১০)","Listen and Type: ২০টি বাক্য shadowing","Mock Test ১ + Review"]],["Week 3: Writing",["Write About the Photo: lesson + exam","Interactive Writing: lesson + exam","Writing Sample: lesson + exam","Linking words ও PREP অভ্যাস","Interactive Writing: আবার","Grammar Practice (লেখার ভুল ঠিক করুন)","Mock Test ২ + Review"]],["Week 4: Speaking ও চূড়ান্ত প্রস্তুতি",["Pronunciation guide পড়ুন","Speak About the Photo (রেকর্ড করুন)","Read Then Speak: lesson + exam","Interactive Speaking: lesson + exam","Speaking Sample + নমুনার সাথে মেলান","Mock Test ৩ + অফিসিয়াল ফ্রি প্র্যাকটিস টেস্ট","পরিবেশ, আইডি, মাইক-ক্যামেরা প্রস্তুত করুন"]]];
const REF={"g":["Grammar guide",[["১. Subject-verb agreement","একবচন কর্তা + verb-s: She goes, He has। Neither/Each/Everyone + একবচন verb। The list of items is long (list = কর্তা)।"],["২. Tense সংকেত","since + বিন্দু (since 2015), for + সময়কাল (for two years) → present perfect। yesterday/ago → past simple। already/yet/just → present perfect।"],["৩. Articles","প্রথম উল্লেখ: a/an; নির্দিষ্ট/জানা: the; সাধারণ বহুবচন/অগণনীয়: কিছু নয় (I like music)। a university, an hour।"],["৪. Prepositions","in (মাস/বছর/শহর), on (দিন/তারিখ), at (সময়/নির্দিষ্ট স্থান)। depend on, interested in, good at, afraid of।"],["৫. Conditionals","Zero: If you heat ice, it melts। First: If it rains, I will stay। Second: If I had time, I would travel। Third: If I had known, I would have come।"],["৬. Passive voice","be + past participle: The report was written by Sam। কর্তা অজানা/অপ্রয়োজনীয় হলে ব্যবহার করুন।"],["৭. Relative clauses","who (ব্যক্তি), which (বস্তু), whose (মালিকানা), where (স্থান)। The man who called is my uncle।"],["৮. Comparatives","taller than, more important than; the most/the -est; as…as। good → better → best।"],["৯. Modals","must (বাধ্যতা), should (পরামর্শ), could/might (সম্ভাবনা)। modal-এর পর verb-এর মূল রূপ: should go।"],["১০. Linking words","However/Although (বিপরীত), Therefore/As a result (ফল), Moreover (যোগ), For example (উদাহরণ)।"],["১১. লেখায় সাধারণ ভুল","বাক্যের শুরুতে capital letter; I সবসময় capital; comma splice এড়ান (দুটি পূর্ণ বাক্য শুধু comma দিয়ে জুড়বেন না: and/but/so বা full stop ব্যবহার করুন); makes us to want ❌ → makes us want ✔; a jeans ❌ → jeans/a pair of jeans ✔।"]]],"w":["Vocabulary",[["Academic","significant – গুরুত্বপূর্ণ<br>estimate – অনুমান করা<br>consequence – পরিণতি<br>constraint – সীমাবদ্ধতা<br>analyze – বিশ্লেষণ করা<br>evidence – প্রমাণ<br>factor – উপাদান<br>approach – পদ্ধতি"],["মত ও যুক্তি","argue – যুক্তি দেওয়া<br>claim – দাবি করা<br>reasonable – যুক্তিসঙ্গত<br>compelling – জোরালো<br>skeptical – সন্দিহান<br>advocate – সমর্থন করা<br>assume – ধরে নেওয়া<br>conclude – সিদ্ধান্তে আসা"],["কাজ ও দৈনন্দিন","deadline – শেষ সময়<br>schedule – সময়সূচি<br>colleague – সহকর্মী<br>afford – সামর্থ্য থাকা<br>commute – যাতায়াত<br>negotiate – দরকষাকষি<br>submit – জমা দেওয়া<br>vacancy – শূন্যপদ"],["পরিবেশ ও প্রযুক্তি","pollution – দূষণ<br>sustainable – টেকসই<br>renewable – নবায়নযোগ্য<br>device – যন্ত্র<br>software – সফটওয়্যার<br>innovation – উদ্ভাবন<br>privacy – গোপনীয়তা<br>mitigate – কমানো"],["Verb ও Adjective","thrive – ফুলেফেঁপে ওঠা<br>scarce – দুষ্প্রাপ্য<br>reliable – নির্ভরযোগ্য<br>flexible – নমনীয়<br>reluctant – অনিচ্ছুক<br>vital – অত্যাবশ্যক<br>obvious – স্পষ্ট<br>fundamental – মৌলিক"],["ছবি বর্ণনার শব্দ","background – পেছনের অংশ<br>foreground – সামনের অংশ<br>in the center – মাঝখানে<br>on the left/right – বাঁদিকে/ডানদিকে<br>wearing – পরে আছে<br>holding – ধরে আছে<br>surrounded by – ঘেরা<br>appears to be – মনে হচ্ছে"],["Linking / signposting","First, / Second, / Finally, – ক্রম<br>For example, / For instance, – উদাহরণ<br>However, / On the other hand, – বিপরীত<br>As a result, / Therefore, – ফল<br>In my opinion, / I believe that – মত<br>In conclusion, / Overall, – উপসংহার"]]],"u":["Pronunciation guide",[["th ধ্বনি","think, three (জিভ দাঁতের মাঝে, বাতাস); this, that (কম্পন)। ত/দ দিয়ে বদলাবেন না।"],["v ও w","very: ওপরের দাঁত নিচের ঠোঁটে; water: ঠোঁট গোল। vine ≠ wine।"],["ship / sheep","short i বনাম long ee: it/eat, live/leave। দৈর্ঘ্যে পার্থক্য রাখুন।"],["Word stress","PHO-to-graph, pho-TO-gra-pher, im-POR-tant। অভিধানে stress চিহ্ন দেখুন। (অফিসিয়াল গাইডে baNAna ঠিক, banaNA ভুল — এ ধরনের stress ভুল স্কোর কমায়।)"],["-ed শেষ","/t/ (walked), /d/ (played), /ɪd/ (wanted, needed)। শেষ ধ্বনি বাদ দেবেন না।"],["-s শেষ","/s/ (cats), /z/ (dogs), /ɪz/ (buses)। বহুবচন ও তৃতীয় পুরুষ স্পষ্ট বলুন।"],["Schwa /ə/","অচাপযুক্ত দুর্বল ধ্বনি: about, banana, today। ইংরেজির সবচেয়ে সাধারণ ধ্বনি।"],["Sentence stress","অর্থবহ শব্দে জোর (noun, verb), function word (of, the) দুর্বল: I WANT to GO to the STORE। যেমন CHInese or JApanese? — বৈপরীত্যে জোর।"],["Linking","শব্দ জুড়ে বলুন: turn off → tur-noff; an apple → a-napple।"],["Intonation","প্রশ্নে (yes/no) শেষে সুর ওঠে; বিবৃতিতে নামে। তালিকায়: ওঠা, ওঠা, নামা।"],["গতি ও ফ্লুয়েন্সি","স্বচ্ছন্দ ইংরেজিতে সাধারণত মিনিটে প্রায় ১৪০ শব্দ বা কাছাকাছি। আপনার প্রথম লক্ষ্য: থামা কমানো ও বাক্যের স্বাভাবিক জায়গায় (clause-এর শেষে) থামা।"]]],"sc":["Scoring",[["Overall ও Subscores","মোট স্কোর ১০–১৬০ (৫ ধাপে) = Listening, Speaking, Reading, Writing — এই চার সাবস্কোরের গড়, ৫-এর নিকটতম ধাপে। Combined subscores: Literacy = (Reading + Writing)/২; Comprehension = (Reading + Listening)/২; Conversation = (Speaking + Listening)/২; Production = (Speaking + Writing)/২।"],["Scoring methods","Right/Wrong: Read and Select, Fill in the Blanks, Read and Complete, Interactive Reading (Highlight the Answer বাদে), Listen and Respond। Partial credit: Listen and Type, Highlight the Answer, Listen and Complete। Writing criteria: Summarize the Conversation, Write About the Photo, Interactive Writing, Writing Sample। Speaking criteria: Speak About the Photo, Read Then Speak, Interactive Speaking, Speaking Sample। (প্রশ্ন-ভিত্তিক কোনো নির্দিষ্ট শতাংশ ভার প্রকাশ করা হয় না।)"],["Writing: ৪টি মানদণ্ড","<b>Content</b> — সব অংশের উত্তর, বিষয়ে থাকা, ব্যাখ্যা/উদাহরণ।<br><b>Discourse coherence</b> — গোছানো কাঠামো, linking words, ধারাবাহিকতা।<br><b>Grammar</b> — structure-এর বৈচিত্র্য ও শুদ্ধতা, punctuation।<br><b>Lexis</b> — শব্দের বৈচিত্র্য, সঠিক শব্দচয়ন, বানান।"],["Speaking: ৬টি মানদণ্ড","Writing-এর চারটির সাথে আরও দুটি: <b>Fluency</b> (গতি, স্বাভাবিক জায়গায় বিরতি, কম থামা/পুনরায় শুরু) ও <b>Pronunciation</b> (বোধগম্যতা, ধ্বনি, word stress, sentence stress, intonation)।"],["স্কোর অনুযায়ী উত্তরের মান (সংক্ষেপে)","<b>১৩০+:</b> প্রশ্নের সব অংশের স্পষ্ট ও উন্নত উত্তর, বৈচিত্র্যময় grammar ও শব্দ, প্রায় নির্ভুল।<br><b>১০০–১২৫:</b> মূল ভাব স্পষ্ট, কিছু বিস্তারিত; ছোটখাটো ভুল বোঝায় বাধা দেয় না।<br><b>৬০–৯৫:</b> আংশিক উত্তর, সীমিত grammar/শব্দ, মাঝে মাঝে বোঝা কঠিন।<br><b>৫৫-এর নিচে:</b> খুব ছোট বা অফ-টপিক, প্রায়ই বোঝা যায় না।"],["AI স্কোরিং","Writing ও Speaking AI দিয়ে স্কোর হয় (বিপুল মানবস্কোর-করা উত্তরে প্রশিক্ষিত)। অফ-টপিক, অর্থহীন বা পুনরাবৃত্তিমূলক উত্তর শনাক্ত করে কম স্কোর দেওয়া হয়। তাই বিষয়ের মধ্যে থেকে স্বাভাবিক ভাষায় বলুন/লিখুন।"]]]};
